pecas.css:
.widget h2.title { 
      font: $(gadget.font); 
      color: var(--nat-gadget-title); 
      border-bottom: 2px solid var(--nat-primary); 
      padding-bottom: 0.5rem; 
      margin-bottom: 1rem; 
      text-transform: uppercase; 
      letter-spacing: 0.5px; 
    }

.footer-col .widget h2.title { color: #ffffff; border-bottom-color: #444; }

.widget ul { list-style: none; padding: 0; margin: 0; }

.widget ul li { padding: 0.6rem 0; border-bottom: 1px dashed #e0e0e0; }

.footer-col .widget ul li { border-bottom-color: #333; }

.widget ul li:last-child { border-bottom: none; }

.widget ul li a { color: inherit; text-decoration: none; transition: all 0.2s; }

.widget ul li a:hover { color: var(--nat-primary); padding-left: 5px; }

#comments { margin-top: 3rem; padding-top: 2rem; border-top: 1px solid #eaeaea; }

#comments h4 { font-weight: bold; font-size: 1.5rem; margin-bottom: 1.5rem; }

.comment-block { background-color: var(--nat-bg); padding: 1.25rem; border-radius: 0.5rem; margin-left: 55px; margin-bottom: 1.5rem; border-left: 4px solid var(--nat-primary); position: relative; }

.avatar-image-container { position: absolute; left: -55px; top: 0; }

.avatar-image-container img { border-radius: 50%; border: 2px solid var(--nat-primary); width: 40px; height: 40px; }

.comment-author { font-weight: bold; font-size: 1rem; margin-bottom: 0.5rem; }

.comment-author a { color: var(--nat-text); text-decoration: none; }

.comment-body { color: #444; line-height: 1.6; font-size: 0.95rem; }

.comment-footer { margin-top: 0.8rem; font-size: 0.85rem; }

.comment-footer a { color: var(--nat-primary); text-decoration: none; font-weight: 600; }

.comment-thread .comment-thread { margin-left: 1.5rem; }

.comment-form { margin-top: 2rem; }

iframe#comment-editor { border: 1px solid #e0e0e0 !important; border-radius: 0.5rem; background: #fff; }

.contact-form-widget { max-width: 100%; margin: 0 auto; }

.contact-form-name, .contact-form-email, .contact-form-email-message { width: 100% !important; max-width: 100% !important; padding: 0.75rem 1rem; margin-bottom: 1.2rem; background-color: #ffffff; border: 1px solid #dee2e6; border-radius: 0.5rem; font-family: inherit; color: var(--nat-text); transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out; }

.contact-form-email-message { min-height: 150px; resize: vertical; }

.contact-form-name:focus, .contact-form-email:focus, .contact-form-email-message:focus { outline: 0; border-color: var(--nat-primary); box-shadow: 0 0 0 0.25rem rgba(143, 188, 143, 0.25); }

.contact-form-button-submit { display: inline-block; font-weight: 600; text-align: center; cursor: pointer; padding: 0.75rem 1.5rem; font-size: 1rem; line-height: 1.5; border-radius: 50rem; color: #121212; background-color: var(--nat-primary); border: 1px solid var(--nat-primary); transition: all 0.2s ease-in-out; width: 100%; text-transform: uppercase; letter-spacing: 0.5px; }

.contact-form-button-submit:hover { background-color: #222222; border-color: #222222; color: #ffffff; }

.contact-form-button-submit:disabled { opacity: 0.6; cursor: not-allowed; }

.contact-form-error-message, .contact-form-success-message { margin-top: 1rem; padding: 1rem; border-radius: 0.5rem; font-weight: 500; text-align: center; clear: both; }

.contact-form-error-message { color: #842029; background-color: #f8d7da; border: 1px solid #f5c2c7; }

.contact-form-success-message { color: #0f5132; background-color: #d1e7dd; border: 1px solid #badbcc; }

.widget.Stats { background-color: var(--nat-bg) !important; padding: 2rem 1rem !important; border-radius: 0.5rem !important; border: 1px dashed #ced4da !important; text-align: center !important; margin-bottom: 2rem !important; box-shadow: 0 0.125rem 0.25rem rgba(0,0,0,0.05) !important; }

.widget.Stats h2.title { border-bottom: none !important; margin-bottom: 0.5rem !important; color: #6c757d !important; font-size: 0.9rem !important; }

.widget.Stats span[dir="ltr"], .widget.Stats .graph-counter-wrapper, .widget.Stats .widget-content > span { display: block !important; font-size: 3.5rem !important; font-weight: 900 !important; color: var(--nat-primary) !important; line-height: 1.1 !important; letter-spacing: -2px !important; }

.widget.Stats span[dir="ltr"]::after { content: "Visitas no Site" !important; display: block !important; font-size: 0.85rem !important; font-weight: 700 !important; color: #999999 !important; text-transform: uppercase !important; letter-spacing: 2px !important; margin-top: 10px !important; }

.widget.Stats img { margin-top: 1.5rem !important; max-width: 100% !important; opacity: 0.25 !important; filter: grayscale(100%) !important; transition: all 0.4s ease !important; border-radius: 4px !important; }

.widget.Stats img:hover { opacity: 1 !important; filter: grayscale(0%) !important; }

#Stats1 .widget-content,
#Stats1 span[dir="ltr"],
#Stats1 .graph-counter-wrapper,
#Stats1 .text-counter-wrapper {
  position: relative;
  z-index: 1;
}

#Stats1 span[dir="ltr"],
#Stats1 .counter-wrapper {
  display: block !important;
  font-family: var(--sl-font-family) !important;
  font-size: clamp(2.5rem, 5vw, 3.5rem) !important;
  font-weight: 900 !important;
  color: var(--nat-primary) !important;
  line-height: 1 !important;
  letter-spacing: -2px !important;
  margin-bottom: 5px !important;
}

#Stats1 .widget-content > span:not([dir="ltr"]):not(.counter-wrapper) {
  display: none !important;
}

.cloud-label-widget-content {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

.cloud-label-widget-content .label-size {
      font-size: 0.85rem !important;
      background-color: #ffffff;
      border: 1px solid #e0e0e0;
      border-radius: 50rem;
      transition: all 0.2s ease-in-out;
    }

.cloud-label-widget-content .label-size a {
      display: inline-block;
      padding: 0.4rem 0.85rem;
      color: var(--nat-text);
      text-decoration: none;
      font-weight: 500;
    }

.cloud-label-widget-content .label-count {
      color: #888;
      font-size: 0.75rem;
      margin-left: 2px;
    }

.cloud-label-widget-content .label-size:hover {
      background-color: var(--nat-primary);
      border-color: var(--nat-primary);
      transform: translateY(-2px);
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
    }

.cloud-label-widget-content .label-size:hover a,
    .cloud-label-widget-content .label-size:hover .label-count {
      color: #121212;
    }

body {
      background: $(body.background);
      color: var(--nat-text);
      font: $(body.font);
      -webkit-font-smoothing: antialiased;
    }

h1, h2, h3, .post-title, .hero-content h1 {
      font: $(heading.font);
    }

.bg-nature-primary { background-color: var(--nat-primary) !important; }

.text-nature-primary { color: var(--nat-primary) !important; }

.site-header { background-color: #ffffff; border-bottom: 2px solid var(--nat-primary); z-index: 1030; }

.site-footer { background-color: var(--nat-footer); color: #e0e0e0; }

.site-footer a { color: var(--nat-primary); text-decoration: none; }

.site-footer a:hover { color: #ffffff; }

mark { background-color: var(--nat-primary); color: #000; padding: 0.1em 0.3em; border-radius: 4px; font-weight: 500; }

.btn-outline-nature { color: var(--nat-primary); border-color: var(--nat-primary); }

.btn-outline-nature:hover { background-color: var(--nat-primary); color: #fff; }

.post-content blockquote {
      background-color: var(--nat-bg);
      border-left: 5px solid var(--nat-primary);
      margin: 2rem 0; padding: 1.5rem; font-size: 1.1rem; font-style: italic; color: #555555;
      border-radius: 0 0.5rem 0.5rem 0; position: relative;
    }

.post-content blockquote p:last-child { margin-bottom: 0; }

.post-content blockquote::before {
      content: "\201C"; font-family: serif; font-size: 6rem; position: absolute;
      top: -1rem; left: 1rem; color: var(--nat-primary); opacity: 0.15; line-height: 1; pointer-events: none;
    }

.sidebar .widget { background: #ffffff; padding: 1.5rem; border-radius: 0.5rem; box-shadow: 0 0.125rem 0.25rem rgba(0,0,0,0.075); margin-bottom: 2rem; }

.footer-col .widget { margin-bottom: 2rem; }

.transition-hover { transition: transform 0.3s ease, box-shadow 0.3s ease; }

.transition-hover:hover { transform: translateY(-5px); box-shadow: 0 .5rem 1rem rgba(0,0,0,.15)!important; }

.hover-primary { transition: color 0.2s; }

.hover-primary:hover { color: var(--nat-primary) !important; }

.post-content img {
      max-width: 100% !important;
      height: auto !important;
      border-radius: 0.5rem;
      display: block;
      margin: 1.5rem auto;
      box-sizing: border-box;
    }

.post-content .separator,
    .post-content .separator a {
      max-width: 100% !important;
      margin-left: 0 !important;
      margin-right: 0 !important;
      text-align: center;
      display: block;
    }

.post-content iframe,
    .post-content object,
    .post-content embed {
      max-width: 100%;
    }

.list-label-widget-content ul {
      list-style: none;
      padding: 0;
      margin: 0;
    }

.list-label-widget-content li {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 0.6rem 0;
      border-bottom: 1px dashed #e0e0e0;
    }

.list-label-widget-content li:last-child {
      border-bottom: none;
    }

.list-label-widget-content li a {
      color: var(--nat-text);
      text-decoration: none;
      font-weight: 500;
      display: flex;
      align-items: center;
      transition: color 0.2s;
    }

.list-label-widget-content li a::before {
      content: "\F288";
      font-family: "bootstrap-icons";
      margin-right: 0.5rem;
      color: var(--nat-primary);
      font-size: 1.1rem;
    }

.list-label-widget-content li a:hover {
      color: var(--nat-primary);
    }

.list-label-widget-content li span {
      background-color: var(--nat-bg);
      color: #666666;
      font-size: 0.75rem;
      font-weight: 700;
      padding: 0.15rem 0.6rem;
      border-radius: 50rem;
    }

.img-relacionada {
      width: 100%;
      height: 220px;
      object-fit: cover;
      border-radius: 0.5rem 0.5rem 0 0;
      transition: all 0.3s ease;
    }

html {
      scroll-behavior: smooth !important;
    }

::-webkit-scrollbar {
      width: 8px;
    }

::-webkit-scrollbar-track {
      background: var(--nat-bg); 
    }

::-webkit-scrollbar-thumb {
      background: var(--nat-primary);
      border-radius: 10px;
    }

::-webkit-scrollbar-thumb:hover {
      background: #7aa97a;
    }

::selection {
      background-color: var(--nat-primary);
      color: #121212;
    }

::-moz-selection {
      background-color: var(--nat-primary);
      color: #121212;
    }

.post-content img {
      transition: transform 0.4s ease, box-shadow 0.4s ease !important;
    }

.post-content img:hover {
      transform: scale(1.02) !important;
      box-shadow: 0 8px 15px rgba(0,0,0,0.1) !important;
    }

.error-page {
      border: 1px dashed #ced4da !important;
    }

.error-page .display-1 i {
      display: inline-block;
      animation: float404 3s ease-in-out infinite;
    }

@keyframes float404 {
      0% { transform: translateY(0px); }
      50% { transform: translateY(-12px); }
      100% { transform: translateY(0px); }
    }

.error-page form input:focus {
      outline: 0;
      box-shadow: 0 0 0 0.25rem rgba(143, 188, 143, 0.25) !important;
    }

#Stats1 {
  background: var(--nat-surface) !important;
  padding: 35px 20px !important;
  border-radius: 16px !important;
  border: 1px solid var(--nat-border) !important;
  text-align: center !important;
  box-shadow: 0 4px 15px rgba(0,0,0,0.02) !important;
  position: relative !important;
  overflow: hidden !important;
  transition: transform 0.3s ease, box-shadow 0.3s ease !important;
  margin-bottom: 30px !important;
}

#Stats1:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 30px rgba(0,0,0,0.08) !important;
  border-color: var(--nat-primary) !important;
}

#Stats1::before {
  content: '\F3E0' !important; 
  font-family: 'bootstrap-icons' !important;
  position: absolute !important;
  top: -20px !important;
  right: -20px !important;
  font-size: 6rem !important;
  color: var(--nat-primary) !important;
  opacity: 0.03 !important;
  transform: rotate(15deg) !important;
  pointer-events: none !important;
  transition: opacity 0.4s ease !important;
  z-index: 0;
}

#Stats1:hover::before {
  opacity: 0.08 !important;
}

#Stats1 h2, 
#Stats1 h2.title {
  font-size: 0.85rem !important;
  font-weight: 800 !important;
  color: var(--nat-text-muted) !important;
  text-transform: uppercase !important;
  letter-spacing: 2px !important;
  margin-bottom: 15px !important;
  border: none !important;
  display: block !important;
  position: relative;
  z-index: 1;
}

#Stats1 h2.title::before {
  display: none !important;
}

#Stats1 span[dir="ltr"]::after,
#Stats1 .counter-wrapper::after {
  content: "Visualizações Totais" !important;
  display: block !important;
  font-size: 0.8rem !important;
  font-weight: 700 !important;
  color: var(--nat-text-muted) !important;
  text-transform: uppercase !important;
  letter-spacing: 1px !important;
  margin-top: 8px !important;
}

#Stats1 img {
  margin-top: 25px !important;
  max-width: 100% !important;
  height: auto !important;
  opacity: 0.3 !important;
  filter: grayscale(100%) !important;
  transition: all 0.4s ease !important;
  border-radius: 8px !important;
  position: relative;
  z-index: 1;
}

#Stats1:hover img {
  opacity: 1 !important;
  filter: grayscale(0%) !important;
}

[data-bs-theme="dark"] #Stats1 {
  background: var(--nat-surface) !important;
}

[data-bs-theme="dark"] #Stats1 img {
  filter: invert(1) grayscale(100%) opacity(0.3) !important;
}

[data-bs-theme="dark"] #Stats1:hover img {
  filter: invert(1) grayscale(0%) opacity(0.8) !important;
}

.mag-video-wrapper {
    position: relative;
    width: 100%;
    padding-bottom: 56.25%; /* Matemática exata para a proporção 16:9 */
    height: 0;
    border-radius: var(--radius, 12px); /* Arredondamento premium */
    overflow: hidden;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08); /* Sombra elegante */
    margin: 2rem 0; /* Espaçamento para respirar no texto */
    background-color: #000; /* Fundo preto enquanto o vídeo carrega */
}

.mag-video-wrapper iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border: none;
}
